const DIFF_RESULT_BRAND = Symbol('diff-result');
const DELTA_BRAND = Symbol('delta');

export function DeepDiff(left, right) {
  const addedEntries = [];
  const changedEntries = [];

  for (const key of Object.keys(right)) {
    if (!Object.prototype.hasOwnProperty.call(left, key)) {
      addedEntries.push([toRootPath(key), right[key]]);
    }
  }

  for (const key of Object.keys(left)) {
    if (
      Object.prototype.hasOwnProperty.call(right, key) &&
      !Object.is(left[key], right[key])
    ) {
      changedEntries.push([
        toRootPath(key),
        { newValue: right[key], oldValue: left[key] },
      ]);
    }
  }

  return {
    [DIFF_RESULT_BRAND]: true,
    addedEntries,
    changedEntries,
  };
}

export class Delta {
  constructor(diffResult) {
    this.diffResult = diffResult;
    this[DELTA_BRAND] = true;
  }
}

export function isDiffResult(value) {
  return Boolean(value && value[DIFF_RESULT_BRAND]);
}

export function isDelta(value) {
  return Boolean(value && value[DELTA_BRAND]);
}

function toRootPath(key) {
  const escapedKey = String(key)
    .replace(/\\/g, '\\\\')
    .replace(/'/g, "\\'");
  return `root['${escapedKey}']`;
}

