export function pythonRepr(value) {
  if (typeof value === 'string') {
    return pythonStringRepr(value);
  }

  if (typeof value === 'bigint') {
    return value.toString();
  }

  if (typeof value === 'number') {
    return formatNumber(value);
  }

  if (typeof value === 'boolean') {
    return value ? 'True' : 'False';
  }

  if (value === null) {
    return 'None';
  }

  if (Array.isArray(value)) {
    return `[${value.map((item) => pythonRepr(item)).join(', ')}]`;
  }

  if (isPlainObject(value)) {
    const parts = Object.keys(value).map(
      (key) => `${pythonRepr(key)}: ${pythonRepr(value[key])}`,
    );
    return `{${parts.join(', ')}}`;
  }

  return pythonStringRepr(String(value));
}

export function pythonStringRepr(value) {
  const quote = chooseQuote(value);
  let result = quote;

  for (const character of value) {
    const codePoint = character.codePointAt(0);

    if (character === '\\') {
      result += '\\\\';
      continue;
    }

    if (character === quote) {
      result += `\\${quote}`;
      continue;
    }

    if (character === '\n') {
      result += '\\n';
      continue;
    }

    if (character === '\r') {
      result += '\\r';
      continue;
    }

    if (character === '\t') {
      result += '\\t';
      continue;
    }

    if (isPrintableCodePoint(codePoint)) {
      result += character;
      continue;
    }

    result += escapeCodePoint(codePoint);
  }

  result += quote;
  return result;
}

function chooseQuote(value) {
  return value.includes("'") && !value.includes('"') ? '"' : "'";
}

function isPrintableCodePoint(codePoint) {
  return (
    codePoint >= 0x20 &&
    codePoint !== 0x7f &&
    !(codePoint >= 0x80 && codePoint <= 0x9f) &&
    !(codePoint >= 0xd800 && codePoint <= 0xdfff)
  );
}

function escapeCodePoint(codePoint) {
  if (codePoint <= 0xff) {
    return `\\x${codePoint.toString(16).padStart(2, '0')}`;
  }

  if (codePoint <= 0xffff) {
    return `\\u${codePoint.toString(16).padStart(4, '0')}`;
  }

  return `\\U${codePoint.toString(16).padStart(8, '0')}`;
}

function formatNumber(value) {
  if (Number.isNaN(value)) {
    return 'nan';
  }

  if (value === Infinity) {
    return 'inf';
  }

  if (value === -Infinity) {
    return '-inf';
  }

  return String(value);
}

function isPlainObject(value) {
  return Object.prototype.toString.call(value) === '[object Object]';
}

